/**
 * 计算最多连续购买次数
 * @param {Array} trades - 交易记录数组
 * @returns {Object} - 包含最大连续购买次数和详细信息的统计结果
 */
function calculateMaxConsecutiveBuys(trades) {
  if (!trades || trades.length === 0) {
    return { maxConsecutive: 0, sequences: [] };
  }

  // 按时间戳排序（确保顺序正确）
  const sortedTrades = [...trades].sort((a, b) =>
    new Date(a.timestamp) - new Date(b.timestamp)
  );

  let maxConsecutive = 0;
  let currentStreak = 0;
  let sequences = []; // 记录所有连续购买序列

  let currentSequence = {
    startIndex: 0,
    trades: [],
    count: 0
  };

  sortedTrades.forEach((trade, index) => {
    if (trade.tradeType === 'buy') {
      currentStreak++;

      // 记录当前连续序列
      if (currentSequence.trades.length === 0) {
        currentSequence.startIndex = index;
      }
      currentSequence.trades.push(trade);
      currentSequence.count = currentStreak;

      // 更新最大值
      if (currentStreak > maxConsecutive) {
        maxConsecutive = currentStreak;
      }
    } else {
      // 遇到非 buy 交易，保存当前序列并重置
      if (currentStreak > 0) {
        sequences.push({
          ...currentSequence,
          endIndex: index - 1
        });
      }
      currentStreak = 0;
      currentSequence = { startIndex: 0, trades: [], count: 0 };
    }
  });

  // 处理最后一段连续序列（如果数组以 buy 结尾）
  if (currentStreak > 0) {
    sequences.push({
      ...currentSequence,
      endIndex: sortedTrades.length - 1
    });
  }

  // 找出最大连续序列的详细信息
  const maxSequences = sequences.filter(s => s.count === maxConsecutive);

  return {
    maxConsecutive,
    totalSequences: sequences.length,
    allSequences: sequences.map(s => ({
      count: s.count,
      startTime: s.trades[0]?.timestamp,
      endTime: s.trades[s.trades.length - 1]?.timestamp,
      totalAmount: s.trades.reduce((sum, t) => sum + parseFloat(t.amount), 0),
      totalFee: s.trades.reduce((sum, t) => sum + parseFloat(t.fee), 0)
    })),
    maxSequenceDetails: maxSequences.map(s => ({
      trades: s.trades,
      startIndex: s.startIndex,
      endIndex: s.endIndex
    }))
  };
}

